//! Evaluates one line of the calc grammar (see SPEC.md) over signed 64-bit integers.
//!
//! Parsing and evaluation happen in a single pass driven by explicit operand and
//! operator stacks (shunting-yard), so neither deeply nested parentheses nor long
//! chains of unary minus can exhaust the call stack. The stacks are kept between
//! calls, so evaluating many lines allocates only when a line is deeper than any
//! seen before.

const std = @import("std");
const Allocator = std.mem.Allocator;

const Evaluator = @This();

gpa: Allocator,
operands: std.ArrayList(i64) = .empty,
operators: std.ArrayList(Operator) = .empty,

/// Reasons an expression has no value. Any of them prints `error`.
pub const EvalError = error{ SyntaxError, DivisionByZero, Overflow };

pub const Error = EvalError || Allocator.Error;

const Operator = enum {
    add,
    sub,
    mul,
    div,
    rem,
    negate,
    /// Marks an open parenthesis; never applied, only matched by `)`.
    open_paren,

    /// Binding strength; operators of higher precedence are applied first.
    fn precedence(op: Operator) u8 {
        return switch (op) {
            .open_paren => 0,
            .add, .sub => 1,
            .mul, .div, .rem => 2,
            .negate => 3,
        };
    }

    fn fromBinary(c: u8) ?Operator {
        return switch (c) {
            '+' => .add,
            '-' => .sub,
            '*' => .mul,
            '/' => .div,
            '%' => .rem,
            else => null,
        };
    }
};

pub fn init(gpa: Allocator) Evaluator {
    return .{ .gpa = gpa };
}

pub fn deinit(self: *Evaluator) void {
    self.operands.deinit(self.gpa);
    self.operators.deinit(self.gpa);
    self.* = undefined;
}

/// Returns true if `line` holds only spaces and tabs, i.e. produces no output.
pub fn isBlank(line: []const u8) bool {
    for (line) |c| {
        if (!isSpace(c)) return false;
    }
    return true;
}

/// Evaluates `expr`, which must not contain the line terminator.
pub fn eval(self: *Evaluator, expr: []const u8) Error!i64 {
    self.operands.clearRetainingCapacity();
    self.operators.clearRetainingCapacity();

    // The grammar alternates operands and binary operators; this tracks which
    // one the next token must be.
    var expect_operand = true;
    var i: usize = 0;
    while (i < expr.len) {
        const c = expr[i];
        if (isSpace(c)) {
            i += 1;
            continue;
        }
        if (expect_operand) {
            switch (c) {
                '0'...'9' => {
                    const end = std.mem.indexOfNonePos(u8, expr, i, "0123456789") orelse expr.len;
                    try self.operands.append(self.gpa, try parseLiteral(expr[i..end]));
                    i = end;
                    expect_operand = false;
                    continue;
                },
                '-' => try self.operators.append(self.gpa, .negate),
                '(' => try self.operators.append(self.gpa, .open_paren),
                else => return error.SyntaxError,
            }
        } else if (Operator.fromBinary(c)) |op| {
            // Left associativity: apply pending operators of equal or higher precedence.
            while (self.topOperator()) |top| {
                if (top.precedence() < op.precedence()) break;
                try self.applyTop();
            }
            try self.operators.append(self.gpa, op);
            expect_operand = true;
        } else if (c == ')') {
            while (true) {
                const top = self.topOperator() orelse return error.SyntaxError;
                if (top == .open_paren) break;
                try self.applyTop();
            }
            _ = self.operators.pop();
        } else {
            return error.SyntaxError;
        }
        i += 1;
    }

    if (expect_operand) return error.SyntaxError;
    while (self.topOperator()) |top| {
        if (top == .open_paren) return error.SyntaxError;
        try self.applyTop();
    }
    std.debug.assert(self.operands.items.len == 1);
    return self.operands.items[0];
}

fn isSpace(c: u8) bool {
    return c == ' ' or c == '\t';
}

fn topOperator(self: *const Evaluator) ?Operator {
    return self.operators.getLastOrNull();
}

/// Pops the top operator and its operands and pushes the result. The
/// alternation enforced by `eval` guarantees the operands are present.
fn applyTop(self: *Evaluator) EvalError!void {
    const op = self.operators.pop().?;
    const operands = &self.operands;
    if (op == .negate) {
        const top = &operands.items[operands.items.len - 1];
        top.* = try std.math.negate(top.*);
        return;
    }
    const rhs = operands.pop().?;
    const lhs = &operands.items[operands.items.len - 1];
    lhs.* = try applyBinary(op, lhs.*, rhs);
}

fn applyBinary(op: Operator, lhs: i64, rhs: i64) EvalError!i64 {
    return switch (op) {
        .add => std.math.add(i64, lhs, rhs),
        .sub => std.math.sub(i64, lhs, rhs),
        .mul => std.math.mul(i64, lhs, rhs),
        .div => std.math.divTrunc(i64, lhs, rhs),
        .rem => {
            if (rhs == 0) return error.DivisionByZero;
            // minInt % -1 is mathematically 0 but traps in hardware.
            if (rhs == -1) return 0;
            return @rem(lhs, rhs);
        },
        .negate, .open_paren => unreachable,
    };
}

/// Parses a non-empty run of decimal digits.
fn parseLiteral(digits: []const u8) EvalError!i64 {
    var value: i64 = 0;
    for (digits) |d| {
        value = try std.math.mul(i64, value, 10);
        value = try std.math.add(i64, value, d - '0');
    }
    return value;
}

fn expectValue(expected: i64, expr: []const u8) !void {
    var evaluator: Evaluator = .init(std.testing.allocator);
    defer evaluator.deinit();
    try std.testing.expectEqual(expected, try evaluator.eval(expr));
}

fn expectFailure(expected: EvalError, expr: []const u8) !void {
    var evaluator: Evaluator = .init(std.testing.allocator);
    defer evaluator.deinit();
    try std.testing.expectError(expected, evaluator.eval(expr));
}

test "precedence and associativity" {
    try expectValue(7, "1 + 2 * 3");
    try expectValue(9, "(1 + 2) * 3");
    try expectValue(5, "1 + 2 * 3 - 4 / 2 % 3");
    try expectValue(3, "10 - 4 - 3");
    try expectValue(1, "100 / 10 / 10");
    try expectValue(70, "2*(3+4)*5");
    try expectValue(42, "\t 42 ");
}

test "unary minus" {
    try expectValue(5, "--5");
    try expectValue(-6, "2 * -3");
    try expectValue(3, "1 - -2");
    try expectValue(-5, "-(2 + 3)");
    try expectValue(-1, "- 2 + 1");
    try expectValue(6, "-2 * -3");
}

test "division truncates toward zero" {
    try expectValue(-3, "-7 / 2");
    try expectValue(3, "7 / 2");
    try expectValue(-1, "-7 % 3");
    try expectValue(1, "7 % -3");
    try expectValue(0, "(-9223372036854775807 - 1) % -1");
    try expectFailure(error.DivisionByZero, "1 / 0");
    try expectFailure(error.DivisionByZero, "5 % (2 - 2)");
}

test "overflow" {
    try expectValue(std.math.maxInt(i64), "9223372036854775807");
    try expectValue(std.math.minInt(i64), "-9223372036854775807 - 1");
    try expectFailure(error.Overflow, "9223372036854775808");
    try expectFailure(error.Overflow, "-9223372036854775808");
    try expectFailure(error.Overflow, "9223372036854775807 + 1");
    try expectFailure(error.Overflow, "(-9223372036854775807 - 1) / -1");
    try expectFailure(error.Overflow, "-(-9223372036854775807 - 1)");
    try expectFailure(error.Overflow, "4611686018427387904 * 2");
}

test "syntax errors" {
    for ([_][]const u8{ "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")", "1 (2)", "-", "1 ** 2", "1\r" }) |expr| {
        try expectFailure(error.SyntaxError, expr);
    }
}

test "deep nesting does not recurse" {
    const depth = 100_000;
    const expr = try std.testing.allocator.alloc(u8, 2 * depth + 1);
    defer std.testing.allocator.free(expr);
    @memset(expr[0..depth], '(');
    expr[depth] = '7';
    @memset(expr[depth + 1 ..], ')');
    try expectValue(7, expr);
}

test isBlank {
    try std.testing.expect(isBlank(""));
    try std.testing.expect(isBlank(" \t "));
    try std.testing.expect(!isBlank(" 1 "));
}

//! `app calc`: 64-bit integer expression evaluator. See the "calc" section of SPEC.md.
//!
//! Reads expressions line by line from standard input and prints each value,
//! or `error`, on its own line. Blank lines print nothing.

const std = @import("std");
const Io = std.Io;

pub const Evaluator = @import("Evaluator.zig");

/// Runs the subcommand: reads standard input and writes standard output.
pub fn run(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    var in_buffer: [64 * 1024]u8 = undefined;
    var stdin_reader = Io.File.stdin().reader(io, &in_buffer);
    var out_buffer: [64 * 1024]u8 = undefined;
    var stdout_writer = Io.File.stdout().writer(io, &out_buffer);

    evaluateLines(gpa, &stdin_reader.interface, &stdout_writer.interface) catch |err| switch (err) {
        error.ReadFailed => return stdin_reader.err.?,
        error.WriteFailed => return stdout_writer.err.?,
        error.OutOfMemory => return error.OutOfMemory,
    };
    stdout_writer.interface.flush() catch return stdout_writer.err.?;
}

/// Evaluates every line of `in` and writes the results to `out`. Lines may be
/// of any length; a final line without a terminating `\n` is still evaluated.
pub fn evaluateLines(
    gpa: std.mem.Allocator,
    in: *Io.Reader,
    out: *Io.Writer,
) error{ ReadFailed, WriteFailed, OutOfMemory }!void {
    var evaluator: Evaluator = .init(gpa);
    defer evaluator.deinit();
    var line: Io.Writer.Allocating = .init(gpa);
    defer line.deinit();

    while (true) {
        line.clearRetainingCapacity();
        _ = in.streamDelimiterEnding(&line.writer, '\n') catch |err| switch (err) {
            error.WriteFailed => return error.OutOfMemory,
            error.ReadFailed => return error.ReadFailed,
        };
        // Unless the stream has ended, the reader is positioned at the delimiter.
        const terminated = if (in.takeByte()) |_| true else |err| switch (err) {
            error.EndOfStream => false,
            error.ReadFailed => return error.ReadFailed,
        };

        const expr = line.written();
        if (!Evaluator.isBlank(expr)) {
            if (evaluator.eval(expr)) |value| {
                try out.print("{d}\n", .{value});
            } else |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                error.SyntaxError, error.DivisionByZero, error.Overflow => try out.writeAll("error\n"),
            }
        }

        if (!terminated) return;
    }
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    var in: Io.Reader = .fixed(input);
    var out: Io.Writer.Allocating = .init(std.testing.allocator);
    defer out.deinit();
    try evaluateLines(std.testing.allocator, &in, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput(
        "1 + 2 * 3\n-7 / 2\n(1 + 2\n9223372036854775807 + 1\n",
        "7\n-3\nerror\nerror\n",
    );
}

test "blank lines and missing final newline" {
    try expectOutput("\n  42  \n\t\n1+1", "42\n2\n");
    try expectOutput("", "");
}

test {
    std.testing.refAllDecls(@This());
}

//! A fixed-capacity LRU cache from short byte strings to short byte strings.
//!
//! Entries live in a pool of nodes addressed by `u32` index. The nodes form a
//! circular doubly linked list in recency order through a sentinel at index 0
//! (`sentinel.next` is the most recently used entry, `sentinel.prev` the least
//! recently used one). A hash map stores node indices and hashes/compares them
//! through the keys held by the nodes, so every key is stored exactly once.
//!
//! Every operation runs in O(1) expected time. The pool never holds more than
//! `capacity` live entries: when full, the evicted node is reused in place.
//! Removals leave tombstones in the open-addressing map, which would make
//! probes for absent keys degrade under steady insert/evict churn, so the map
//! is rehashed in place after a bounded number of removals (amortized O(1)).

const std = @import("std");
const Allocator = std.mem.Allocator;

const Cache = @This();

/// Maximum length in bytes of a key or a value.
pub const max_len = 64;

const Index = u32;
const sentinel: Index = 0;
/// Terminates the free list.
const nil: Index = std.math.maxInt(Index);

const Node = struct {
    /// Cached `hashKey(key())`, so rehashing never rereads key bytes.
    hash: u64,
    prev: Index,
    next: Index,
    key_len: u8,
    value_len: u8,
    key_buf: [max_len]u8,
    value_buf: [max_len]u8,

    fn key(node: *const Node) []const u8 {
        return node.key_buf[0..node.key_len];
    }

    fn value(node: *const Node) []const u8 {
        return node.value_buf[0..node.value_len];
    }

    fn setKey(node: *Node, bytes: []const u8) void {
        @memcpy(node.key_buf[0..bytes.len], bytes);
        node.key_len = @intCast(bytes.len);
        node.hash = hashKey(bytes);
    }

    fn setValue(node: *Node, bytes: []const u8) void {
        @memcpy(node.value_buf[0..bytes.len], bytes);
        node.value_len = @intCast(bytes.len);
    }
};

/// Hashes and compares stored node indices by the keys of their nodes.
const IndexContext = struct {
    nodes: []const Node,

    pub fn hash(ctx: IndexContext, index: Index) u64 {
        return ctx.nodes[index].hash;
    }

    pub fn eql(_: IndexContext, a: Index, b: Index) bool {
        // Each live key is held by exactly one node.
        return a == b;
    }
};

/// Looks up stored node indices by key bytes.
const KeyContext = struct {
    nodes: []const Node,

    pub fn hash(_: KeyContext, key: []const u8) u64 {
        return hashKey(key);
    }

    pub fn eql(ctx: KeyContext, key: []const u8, index: Index) bool {
        return std.mem.eql(u8, key, ctx.nodes[index].key());
    }
};

fn hashKey(key: []const u8) u64 {
    return std.hash.Wyhash.hash(0, key);
}

/// A low load factor keeps linear probe sequences short even with tombstones.
const max_load_percentage = 50;
const Map = std.HashMapUnmanaged(Index, void, IndexContext, max_load_percentage);

/// The map is rehashed once removals since the last rehash exceed
/// `map.capacity() / tombstone_divisor`, bounding the share of tombstones.
const tombstone_divisor = 8;

pub const InitError = Allocator.Error || error{CapacityTooLarge};

gpa: Allocator,
capacity: Index,
/// Index 0 is the sentinel; all others are live entries or on the free list.
nodes: std.ArrayList(Node),
map: Map,
/// Head of the list of unused nodes, chained through `Node.next`.
free_head: Index,
/// Upper bound on the tombstones currently in `map`.
removals_since_rehash: usize,

pub fn init(gpa: Allocator, capacity: usize) InitError!Cache {
    std.debug.assert(capacity >= 1);
    // One index is taken by the sentinel and one is reserved as `nil`.
    if (capacity > std.math.maxInt(Index) - 2) return error.CapacityTooLarge;

    var nodes: std.ArrayList(Node) = .empty;
    try nodes.append(gpa, .{
        .hash = 0,
        .prev = sentinel,
        .next = sentinel,
        .key_len = 0,
        .value_len = 0,
        .key_buf = undefined,
        .value_buf = undefined,
    });
    return .{
        .gpa = gpa,
        .capacity = @intCast(capacity),
        .nodes = nodes,
        .map = .empty,
        .free_head = nil,
        .removals_since_rehash = 0,
    };
}

pub fn deinit(cache: *Cache) void {
    cache.map.deinit(cache.gpa);
    cache.nodes.deinit(cache.gpa);
    cache.* = undefined;
}

/// Number of entries currently held.
pub fn count(cache: *const Cache) usize {
    return cache.map.count();
}

/// Returns the value stored under `key` and marks it most recently used.
/// The returned slice is valid until the next mutating call.
pub fn get(cache: *Cache, key: []const u8) ?[]const u8 {
    const index = cache.find(key) orelse return null;
    cache.moveToFront(index);
    return cache.nodes.items[index].value();
}

/// Inserts or overwrites `key`, marking it most recently used. Evicts the
/// least recently used entry if the cache would exceed its capacity.
pub fn put(cache: *Cache, key: []const u8, value: []const u8) Allocator.Error!void {
    std.debug.assert(key.len <= max_len and value.len <= max_len);

    if (cache.find(key)) |index| {
        cache.nodes.items[index].setValue(value);
        cache.moveToFront(index);
        return;
    }

    // Reserve map space first so that a failed allocation leaves the cache intact.
    try cache.map.ensureUnusedCapacityContext(cache.gpa, 1, cache.indexContext());

    const index = if (cache.map.count() >= cache.capacity) blk: {
        const lru = cache.nodes.items[sentinel].prev;
        cache.unlink(lru);
        const removed = cache.map.removeContext(lru, cache.indexContext());
        std.debug.assert(removed);
        cache.noteRemoval();
        break :blk lru;
    } else try cache.allocNode();

    const node = &cache.nodes.items[index];
    node.setKey(key);
    node.setValue(value);
    cache.linkFront(index);
    cache.map.putAssumeCapacityNoClobberContext(index, {}, cache.indexContext());
}

/// Removes `key`. Returns whether it was present.
pub fn remove(cache: *Cache, key: []const u8) bool {
    const kv = cache.map.fetchRemoveAdapted(key, cache.keyContext()) orelse return false;
    const index = kv.key;
    cache.noteRemoval();
    cache.unlink(index);
    cache.nodes.items[index].next = cache.free_head;
    cache.free_head = index;
    return true;
}

fn find(cache: *const Cache, key: []const u8) ?Index {
    if (key.len > max_len) return null;
    return cache.map.getKeyAdapted(key, cache.keyContext());
}

fn noteRemoval(cache: *Cache) void {
    cache.removals_since_rehash += 1;
    if (cache.removals_since_rehash > cache.map.capacity() / tombstone_divisor) {
        cache.map.rehash(cache.indexContext());
        cache.removals_since_rehash = 0;
    }
}

fn allocNode(cache: *Cache) Allocator.Error!Index {
    if (cache.free_head != nil) {
        const index = cache.free_head;
        cache.free_head = cache.nodes.items[index].next;
        return index;
    }
    const index: Index = @intCast(cache.nodes.items.len);
    _ = try cache.nodes.addOne(cache.gpa);
    return index;
}

fn unlink(cache: *Cache, index: Index) void {
    const nodes = cache.nodes.items;
    const node = &nodes[index];
    nodes[node.prev].next = node.next;
    nodes[node.next].prev = node.prev;
}

fn linkFront(cache: *Cache, index: Index) void {
    const nodes = cache.nodes.items;
    const first = nodes[sentinel].next;
    nodes[index].prev = sentinel;
    nodes[index].next = first;
    nodes[first].prev = index;
    nodes[sentinel].next = index;
}

fn moveToFront(cache: *Cache, index: Index) void {
    if (cache.nodes.items[sentinel].next == index) return;
    cache.unlink(index);
    cache.linkFront(index);
}

fn indexContext(cache: *const Cache) IndexContext {
    return .{ .nodes = cache.nodes.items };
}

fn keyContext(cache: *const Cache) KeyContext {
    return .{ .nodes = cache.nodes.items };
}

const testing = std.testing;

test "evicts the least recently used entry" {
    var cache: Cache = try .init(testing.allocator, 2);
    defer cache.deinit();

    try cache.put("a", "1");
    try cache.put("b", "2");
    try testing.expectEqualStrings("1", cache.get("a").?);
    try cache.put("c", "3");
    try testing.expectEqual(null, cache.get("b"));
    try testing.expectEqualStrings("1", cache.get("a").?);
    try testing.expectEqualStrings("3", cache.get("c").?);
    try testing.expectEqual(2, cache.count());
}

test "overwrite refreshes recency and value" {
    var cache: Cache = try .init(testing.allocator, 2);
    defer cache.deinit();

    try cache.put("a", "1");
    try cache.put("b", "2");
    try cache.put("a", "9");
    try cache.put("c", "3");
    try testing.expectEqualStrings("9", cache.get("a").?);
    try testing.expectEqual(null, cache.get("b"));
    try testing.expectEqualStrings("3", cache.get("c").?);
}

test "remove frees a slot that is reused" {
    var cache: Cache = try .init(testing.allocator, 2);
    defer cache.deinit();

    try cache.put("x", "1");
    try testing.expect(cache.remove("x"));
    try testing.expect(!cache.remove("x"));
    try testing.expectEqual(0, cache.count());
    try testing.expectEqual(null, cache.get("x"));

    try cache.put("y", "2");
    try cache.put("z", "3");
    try testing.expectEqual(2, cache.count());
    try testing.expectEqual(3, cache.nodes.items.len); // sentinel + 2
    try testing.expectEqualStrings("2", cache.get("y").?);
    try testing.expectEqualStrings("3", cache.get("z").?);
}

test "capacity one" {
    var cache: Cache = try .init(testing.allocator, 1);
    defer cache.deinit();

    try cache.put("a", "1");
    try cache.put("b", "2");
    try testing.expectEqual(null, cache.get("a"));
    try testing.expectEqualStrings("2", cache.get("b").?);
    try testing.expectEqual(1, cache.count());
}

test "keys and values of maximum length" {
    var cache: Cache = try .init(testing.allocator, 4);
    defer cache.deinit();

    const long_key = "k" ** max_len;
    const long_value = "v" ** max_len;
    try cache.put(long_key, long_value);
    try testing.expectEqualStrings(long_value, cache.get(long_key).?);
    try testing.expectEqual(null, cache.get(long_key ++ "k"));
    try testing.expect(!cache.remove(long_key ++ "k"));
}

test "matches a reference model under random operations" {
    const gpa = testing.allocator;
    var prng: std.Random.DefaultPrng = .init(0x5eed);
    const random = prng.random();

    const capacity = 16;
    var cache: Cache = try .init(gpa, capacity);
    defer cache.deinit();

    // Reference: keys in recency order, most recent last.
    var model: std.ArrayList(struct { key: u8, value: u32 }) = .empty;
    defer model.deinit(gpa);

    for (0..20_000) |_| {
        const k: u8 = random.uintLessThan(u8, 40);
        const key: []const u8 = &.{ 'a' + k / 26, 'a' + k % 26 };
        const found: ?usize = for (model.items, 0..) |e, i| {
            if (e.key == k) break i;
        } else null;

        switch (random.uintLessThan(u8, 3)) {
            0 => {
                const v = random.int(u32);
                var buf: [16]u8 = undefined;
                try cache.put(key, try std.fmt.bufPrint(&buf, "{d}", .{v}));
                if (found) |i| _ = model.orderedRemove(i);
                if (model.items.len == capacity) _ = model.orderedRemove(0);
                try model.append(gpa, .{ .key = k, .value = v });
            },
            1 => {
                const got = cache.get(key);
                if (found) |i| {
                    const e = model.orderedRemove(i);
                    try model.append(gpa, e);
                    var buf: [16]u8 = undefined;
                    try testing.expectEqualStrings(try std.fmt.bufPrint(&buf, "{d}", .{e.value}), got.?);
                } else {
                    try testing.expectEqual(null, got);
                }
            },
            else => {
                try testing.expectEqual(found != null, cache.remove(key));
                if (found) |i| _ = model.orderedRemove(i);
            },
        }
        try testing.expectEqual(model.items.len, cache.count());
    }
}

//! `app lru`: LRU cache simulator. See the "lru" section of SPEC.md.
//!
//! The first line holds the capacity; every later line is one command
//! (`SET <key> <value>`, `GET <key>`, `DEL <key>` or `SIZE`). Input is
//! streamed line by line, so memory is bounded by the cache contents rather
//! than by the input size. Lines that are not a well-formed command are
//! ignored, as is all input after an invalid capacity line.

const std = @import("std");
const Io = std.Io;

pub const Cache = @import("Cache.zig");

const max_capacity = 1_000_000;

/// Runs the subcommand: reads standard input and writes standard output.
/// Must exit with status 0 on any input, per SPEC.md.
pub fn run(init: std.process.Init) !void {
    const io = init.io;

    var in_buf: [64 * 1024]u8 = undefined;
    var stdin = Io.File.stdin().readerStreaming(io, &in_buf);
    var out_buf: [64 * 1024]u8 = undefined;
    var stdout = Io.File.stdout().writerStreaming(io, &out_buf);

    simulate(init.gpa, &stdin.interface, &stdout.interface) catch |err| switch (err) {
        error.ReadFailed => return stdin.err.?,
        error.WriteFailed => return stdout.err.?,
        else => |e| return e,
    };
    stdout.interface.flush() catch return stdout.err.?;
}

pub const SimulateError = Io.Reader.Error || Io.Writer.Error || Cache.InitError;

/// Executes the commands read from `in`, writing their output to `out`.
/// The caller is responsible for flushing `out`.
pub fn simulate(gpa: std.mem.Allocator, in: *Io.Reader, out: *Io.Writer) SimulateError!void {
    const first = try nextLine(in) orelse return;
    const capacity = parseCapacity(first) orelse return;

    var cache: Cache = try .init(gpa, capacity);
    defer cache.deinit();

    while (try nextLine(in)) |line| {
        const command = Command.parse(line) orelse continue;
        switch (command) {
            .set => |set| try cache.put(set.key, set.value),
            .get => |key| try out.print("{s}\n", .{cache.get(key) orelse "NULL"}),
            .del => |key| try out.print("{d}\n", .{@intFromBool(cache.remove(key))}),
            .size => try out.print("{d}\n", .{cache.count()}),
        }
    }
}

/// Returns the next line without its terminator (`\n`, or `\r\n`), or null at
/// end of input. Lines too long to buffer cannot be valid commands; they are
/// skipped.
fn nextLine(in: *Io.Reader) Io.Reader.Error!?[]const u8 {
    while (true) {
        const line = in.takeDelimiter('\n') catch |err| switch (err) {
            error.StreamTooLong => {
                _ = in.discardDelimiterInclusive('\n') catch |e| switch (e) {
                    error.EndOfStream => return null,
                    error.ReadFailed => return error.ReadFailed,
                };
                continue;
            },
            error.ReadFailed => return error.ReadFailed,
        } orelse return null;
        return std.mem.trimEnd(u8, line, "\r");
    }
}

fn parseCapacity(line: []const u8) ?usize {
    const trimmed = std.mem.trim(u8, line, " \t");
    const capacity = std.fmt.parseUnsigned(usize, trimmed, 10) catch return null;
    if (capacity < 1 or capacity > max_capacity) return null;
    return capacity;
}

const Command = union(enum) {
    set: struct { key: []const u8, value: []const u8 },
    get: []const u8,
    del: []const u8,
    size,

    const Name = enum { SET, GET, DEL, SIZE };

    /// Parses one command line, or returns null if it is malformed.
    fn parse(line: []const u8) ?Command {
        var tokens = std.mem.tokenizeScalar(u8, line, ' ');
        const name = std.meta.stringToEnum(Name, tokens.next() orelse return null) orelse
            return null;
        const command: Command = switch (name) {
            .SET => .{ .set = .{
                .key = validToken(tokens.next()) orelse return null,
                .value = validToken(tokens.next()) orelse return null,
            } },
            .GET => .{ .get = validToken(tokens.next()) orelse return null },
            .DEL => .{ .del = validToken(tokens.next()) orelse return null },
            .SIZE => .size,
        };
        if (tokens.next() != null) return null;
        return command;
    }

    fn validToken(token: ?[]const u8) ?[]const u8 {
        const t = token orelse return null;
        return if (t.len <= Cache.max_len) t else null;
    }
};

fn expectOutput(input: []const u8, expected: []const u8) !void {
    var in: Io.Reader = .fixed(input);
    var out: Io.Writer.Allocating = .init(std.testing.allocator);
    defer out.deinit();
    try simulate(std.testing.allocator, &in, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n", "1\nNULL\n2\n");
}

test "delete and size" {
    try expectOutput("3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x\n", "1\n0\n0\nNULL\n");
}

test "last line without newline and CRLF endings" {
    try expectOutput("1\r\nSET a 1\r\nGET a", "1\n");
}

test "malformed lines are ignored" {
    try expectOutput("2\n\nFOO a\nGET\nSET a\nSET a 1 2\nSIZE x\nSIZE\n", "0\n");
}

test "invalid capacity produces no output" {
    try expectOutput("0\nSIZE\n", "");
    try expectOutput("abc\nSIZE\n", "");
    try expectOutput("", "");
}

test {
    std.testing.refAllDecls(@This());
}

